export const getBooksByGrade = (grade: string | number) => {
  const numericGrade = typeof grade === 'string' ? parseInt(grade, 10) : grade;
  
  if (numericGrade === 6) {
    return booksData.grade6;
  } else if (numericGrade === 7) {
    return booksData.grade7;
  } else if (numericGrade === 8) {
    return booksData.grade8;
  } else if (numericGrade === 9) {
    return booksData.grade9;
  } else if (numericGrade === 10) {
    return [...booksData.grade10, ...booksData.common, ...booksData.advanced];
  } else if (numericGrade === 11) {
    return [...booksData.common, ...booksData.advanced];
  }
  
  return booksData.common;
};
